(function () {
  "use strict";

  const { COURSES, DEFAULT_PROFILE, DEFAULT_REGISTRATIONS } = window.AURORA;
  const STORAGE_KEYS = {
    registrations: "aurora.registrations.v1",
    profile: "aurora.profile.v1"
  };

  const memoryStore = {};

  function readStorage(key, fallback) {
    try {
      const value = window.localStorage.getItem(key);
      return value === null ? fallback : JSON.parse(value);
    } catch (error) {
      return Object.prototype.hasOwnProperty.call(memoryStore, key) ? memoryStore[key] : fallback;
    }
  }

  function writeStorage(key, value) {
    memoryStore[key] = value;
    try {
      window.localStorage.setItem(key, JSON.stringify(value));
    } catch (error) {
      // The app remains usable in private or storage-restricted contexts.
    }
  }

  function getCourseById(id) {
    return COURSES.find(function (course) {
      return course.id === id;
    });
  }

  function getRegistrations() {
    const stored = readStorage(STORAGE_KEYS.registrations, null);
    if (!Array.isArray(stored)) {
      writeStorage(STORAGE_KEYS.registrations, DEFAULT_REGISTRATIONS);
      return DEFAULT_REGISTRATIONS.slice();
    }
    return stored.filter(function (id) {
      return Boolean(getCourseById(id));
    });
  }

  function setRegistrations(ids) {
    const uniqueIds = ids.filter(function (id, index) {
      return getCourseById(id) && ids.indexOf(id) === index;
    });
    writeStorage(STORAGE_KEYS.registrations, uniqueIds);
    updateRegistrationCount();
    return uniqueIds;
  }

  function isRegistered(courseId) {
    return getRegistrations().indexOf(courseId) !== -1;
  }

  function addRegistration(courseId) {
    const registrations = getRegistrations();
    if (getCourseById(courseId) && registrations.indexOf(courseId) === -1) {
      registrations.push(courseId);
      return setRegistrations(registrations);
    }
    return registrations;
  }

  function removeRegistration(courseId) {
    return setRegistrations(
      getRegistrations().filter(function (id) {
        return id !== courseId;
      })
    );
  }

  function getProfile() {
    const stored = readStorage(STORAGE_KEYS.profile, {});
    return Object.assign({}, DEFAULT_PROFILE, stored && typeof stored === "object" ? stored : {});
  }

  function saveProfile(updates) {
    const profile = Object.assign({}, getProfile(), updates);
    writeStorage(STORAGE_KEYS.profile, profile);
    return profile;
  }

  function getInitials(name) {
    return String(name || "")
      .trim()
      .split(/\s+/)
      .slice(0, 2)
      .map(function (part) {
        return part.charAt(0).toUpperCase();
      })
      .join("");
  }

  function escapeHtml(value) {
    return String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  function updateRegistrationCount() {
    const count = getRegistrations().length;
    document.querySelectorAll("[data-registration-count]").forEach(function (element) {
      element.textContent = String(count);
    });
    document.querySelectorAll("[data-registration-label]").forEach(function (element) {
      element.textContent = count === 1 ? "course registered" : "courses registered";
    });
    document.querySelectorAll("[data-credits-count]").forEach(function (element) {
      const credits = getRegistrations().reduce(function (total, id) {
        const course = getCourseById(id);
        return total + (course ? course.credits : 0);
      }, 0);
      element.textContent = String(credits);
    });
  }

  function createCourseCard(course, options) {
    const settings = options || {};
    const meta = window.AURORA.DEPARTMENTS[course.department];
    const registered = isRegistered(course.id);
    const titleId = "course-" + course.id + "-title";
    const openSeats = Math.max(0, course.seatsAvailable);
    const seatPercent = Math.min(100, Math.round((openSeats / course.capacity) * 100));
    const seatLabel = openSeats + " of " + course.capacity + " seats open";
    const article = document.createElement("article");
    article.className = "course-card";
    article.setAttribute("aria-labelledby", titleId);
    article.style.setProperty("--accent", meta.accent);
    article.style.setProperty("--accent-dark", meta.dark);
    article.style.setProperty("--accent-soft", meta.soft);

    const action = registered
      ? '<a class="btn btn-small btn-registered" href="registration.html">View schedule<span class="sr-only"> for ' +
        escapeHtml(course.code) +
        "</span></a>"
      : '<a class="btn btn-small" href="registration.html?course=' +
        encodeURIComponent(course.id) +
        '">Choose course<span class="sr-only"> — ' +
        escapeHtml(course.code) +
        " " +
        escapeHtml(course.title) +
        "</span></a>";

    article.innerHTML =
      '<div class="course-card__top">' +
      '<span class="dept-badge">' +
      escapeHtml(course.department) +
      "</span>" +
      '<span class="course-code">' +
      escapeHtml(course.code) +
      "</span>" +
      "</div>" +
      '<h3 class="course-title" id="' +
      titleId +
      '"><a class="course-title-link" href="registration.html?course=' +
      encodeURIComponent(course.id) +
      '">' +
      escapeHtml(course.title) +
      '<svg class="icon" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M7.5 4.5 13 10l-5.5 5.5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></a></h3>' +
      '<p class="course-description">' +
      escapeHtml(course.description) +
      "</p>" +
      '<ul class="course-facts" role="list">' +
      '<li><svg class="icon" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><rect x="3" y="4" width="14" height="13" rx="2" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M6.5 2.5v3M13.5 2.5v3M3 8h14" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg><span>' +
      escapeHtml(course.schedule) +
      "</span></li>" +
      '<li><svg class="icon" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M10 17s5.5-5.1 5.5-9a5.5 5.5 0 1 0-11 0c0 3.9 5.5 9 5.5 9Z" fill="none" stroke="currentColor" stroke-width="1.6"/><circle cx="10" cy="8" r="1.8" fill="currentColor"/></svg><span>' +
      escapeHtml(course.format) +
      " · " +
      escapeHtml(course.location) +
      "</span></li>" +
      '<li><svg class="icon" viewBox="0 0 20 20" aria-hidden="true" focusable="false"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H16v12H6.5A2.5 2.5 0 0 0 4 17.5v-12Z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M4 17.5V5.5M16 15H6.5A2.5 2.5 0 0 0 4 17.5" fill="none" stroke="currentColor" stroke-width="1.6"/></svg><span>' +
      escapeHtml(course.credits) +
      " credits · Level " +
      escapeHtml(course.level) +
      "</span></li>" +
      "</ul>" +
      '<div class="seat-block">' +
      '<div class="seat-row"><span class="seat-label"><strong>' +
      escapeHtml(openSeats) +
      "</strong> of " +
      escapeHtml(course.capacity) +
      ' seats open</span><span class="format-badge">' +
      escapeHtml(course.format) +
      "</span></div>" +
      '<div class="seat-meter" role="img" aria-label="' +
      escapeHtml(seatLabel) +
      '"><span style="width: ' +
      seatPercent +
      '%"></span></div>' +
      "</div>" +
      '<div class="course-card__footer"><span class="instructor">' +
      escapeHtml(course.instructor) +
      "</span>" +
      action +
      "</div>";

    if (settings.highlight) {
      article.classList.add("course-card--featured");
    }

    return article;
  }

  function renderEmptySchedule(container) {
    container.innerHTML =
      '<div class="empty-state">' +
      '<span class="empty-icon" aria-hidden="true">' +
      '<svg viewBox="0 0 48 48" focusable="false"><path d="M12 10h24a4 4 0 0 1 4 4v24a4 4 0 0 1-4 4H12a4 4 0 0 1-4-4V14a4 4 0 0 1 4-4Z" fill="none" stroke="currentColor" stroke-width="2.5"/><path d="M16 6v8M32 6v8M8 20h32M17 28h14M17 34h9" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg>' +
      "</span>" +
      "<h3>Your schedule is wide open</h3>" +
      '<p>Find a course that sparks your curiosity and add it to your Spring schedule.</p>' +
      '<a class="btn" href="courses.html">Browse courses</a>' +
      "</div>";
  }

  document.addEventListener("DOMContentLoaded", function () {
    updateRegistrationCount();
    document.querySelectorAll("[data-current-year]").forEach(function (element) {
      element.textContent = String(new Date().getFullYear());
    });
  });

  window.AURORA_APP = {
    getCourseById,
    getRegistrations,
    setRegistrations,
    isRegistered,
    addRegistration,
    removeRegistration,
    getProfile,
    saveProfile,
    getInitials,
    updateRegistrationCount,
    createCourseCard,
    renderEmptySchedule,
    escapeHtml
  };
})();

:root {
  --ink: #19152d;
  --ink-soft: #443e5c;
  --muted: #68617e;
  --paper: #fffdfa;
  --surface: #ffffff;
  --line: #e8e3f0;
  --line-strong: #d6cfe4;
  --violet: #5b3fd6;
  --violet-dark: #4229ad;
  --violet-soft: #eee9ff;
  --coral: #e85572;
  --coral-soft: #ffe8ed;
  --teal: #0d8f7d;
  --teal-dark: #08685b;
  --teal-soft: #dff8f2;
  --gold: #d28a00;
  --gold-soft: #fff3d4;
  --sky-soft: #e4f3ff;
  --danger: #a91d24;
  --danger-soft: #fff0f0;
  --success: #08684b;
  --success-soft: #e5f9f0;
  --shadow-sm: 0 8px 24px rgba(44, 28, 92, 0.07);
  --shadow-md: 0 18px 48px rgba(44, 28, 92, 0.12);
  --shadow-lg: 0 30px 70px rgba(44, 28, 92, 0.18);
  --radius-sm: 12px;
  --radius-md: 20px;
  --radius-lg: 28px;
  --radius-xl: 36px;
  --container: 1180px;
  --font: "Segoe UI", "Avenir Next", "Helvetica Neue", Arial, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  background: var(--paper);
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body:has(dialog[open]) {
  overflow: hidden;
}

img,
svg {
  max-width: 100%;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

a {
  color: var(--violet-dark);
  text-decoration-thickness: 0.09em;
  text-underline-offset: 0.18em;
}

a:hover {
  color: var(--violet);
}

h1,
h2,
h3,
p,
dl,
dd {
  margin-top: 0;
}

h1,
h2,
h3 {
  line-height: 1.12;
  letter-spacing: -0.03em;
}

h1 {
  font-size: clamp(2.6rem, 6vw, 4.8rem);
}

h2 {
  font-size: clamp(1.85rem, 3.5vw, 2.8rem);
}

h3 {
  font-size: 1.22rem;
}

[hidden] {
  display: none !important;
}

.container {
  width: min(calc(100% - 2.5rem), var(--container));
  margin-inline: auto;
}

main:focus {
  outline: none;
}

.sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.skip-link {
  position: fixed;
  top: 0.75rem;
  left: 0.75rem;
  z-index: 1000;
  padding: 0.75rem 1rem;
  border-radius: 0.6rem;
  background: var(--ink);
  color: #fff;
  font-weight: 700;
  transform: translateY(-160%);
  transition: transform 150ms ease;
}

.skip-link:focus {
  transform: translateY(0);
  color: #fff;
}

*:focus-visible {
  outline: 3px solid #1369c9;
  outline-offset: 3px;
}

::selection {
  background: #d8cbff;
  color: var(--ink);
}

.icon {
  width: 1.1em;
  height: 1.1em;
  flex: 0 0 auto;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 253, 250, 0.94);
  border-bottom: 1px solid rgba(232, 227, 240, 0.9);
  backdrop-filter: blur(16px);
}

.site-header::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 4px;
  background: linear-gradient(90deg, var(--violet), #c43c91 45%, var(--coral) 70%, #f0b429);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  min-height: 80px;
  padding-block: 0.7rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.7rem;
  color: var(--ink);
  text-decoration: none;
  border-radius: var(--radius-sm);
}

.brand:hover {
  color: var(--ink);
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 14px;
  color: #fff;
  background: linear-gradient(135deg, var(--violet) 5%, #a63cc4 55%, var(--coral));
  box-shadow: 0 7px 18px rgba(91, 63, 214, 0.28);
  transform: rotate(-3deg);
}

.brand-mark svg {
  width: 26px;
  height: 26px;
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.brand-text > span {
  font-size: 1.22rem;
  font-weight: 800;
  letter-spacing: -0.03em;
}

.brand-text small {
  margin-top: 0.25rem;
  color: var(--muted);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.main-nav ul {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.2rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.main-nav a {
  display: inline-flex;
  align-items: center;
  gap: 0.42rem;
  padding: 0.58rem 0.82rem;
  border-radius: 999px;
  color: var(--ink-soft);
  font-size: 0.93rem;
  font-weight: 650;
  text-decoration: none;
  transition: background 150ms ease, color 150ms ease;
}

.main-nav a:hover {
  background: #f3effc;
  color: var(--violet-dark);
}

.main-nav a[aria-current="page"] {
  background: var(--violet-soft);
  color: var(--violet-dark);
}

.nav-badge {
  display: inline-grid;
  place-items: center;
  min-width: 1.4rem;
  height: 1.4rem;
  padding-inline: 0.35rem;
  border-radius: 999px;
  background: var(--violet);
  color: #fff;
  font-size: 0.71rem;
  font-weight: 800;
  line-height: 1;
}

.main-nav a[aria-current="page"] .nav-badge {
  background: var(--violet-dark);
}

.hero {
  position: relative;
  overflow: hidden;
  padding: clamp(3.5rem, 7vw, 6rem) 0 5.4rem;
  background:
    radial-gradient(circle at 6% 16%, rgba(255, 205, 103, 0.36), transparent 30%),
    radial-gradient(circle at 88% 8%, rgba(113, 224, 207, 0.27), transparent 30%),
    linear-gradient(125deg, #fff9ec 0%, #f7f1ff 48%, #eafaf6 100%);
}

.hero-shape {
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
}

.hero-shape--one {
  width: 230px;
  height: 230px;
  right: -90px;
  bottom: 60px;
  border: 38px solid rgba(232, 85, 114, 0.11);
}

.hero-shape--two {
  width: 140px;
  height: 140px;
  left: 42%;
  top: -55px;
  background: rgba(91, 63, 214, 0.08);
  transform: rotate(28deg);
  border-radius: 38px;
}

.hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(320px, 0.85fr);
  align-items: center;
  gap: clamp(2rem, 5vw, 4.5rem);
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  margin-bottom: 1.3rem;
  padding: 0.43rem 0.8rem;
  border: 1px solid rgba(91, 63, 214, 0.16);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.65);
  color: var(--violet-dark);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.eyebrow--ink {
  border: 0;
  padding: 0;
  background: transparent;
  color: var(--violet);
}

.eyebrow-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
  box-shadow: 0 0 0 4px rgba(232, 85, 114, 0.14);
}

.hero h1 {
  max-width: 11ch;
  margin-bottom: 1.5rem;
  font-weight: 800;
  line-height: 0.99;
  letter-spacing: -0.055em;
}

.text-gradient {
  background: linear-gradient(112deg, var(--violet) 4%, #a73aa8 52%, var(--coral) 94%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hero-lead {
  max-width: 57ch;
  margin-bottom: 1.8rem;
  color: var(--ink-soft);
  font-size: clamp(1.02rem, 1.8vw, 1.16rem);
}

.hero-search {
  max-width: 620px;
  margin-bottom: 1.9rem;
}

.hero-search > label {
  display: block;
  margin-bottom: 0.5rem;
  color: var(--ink-soft);
  font-size: 0.82rem;
  font-weight: 700;
}

.search-box {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.35rem;
  border: 1px solid rgba(91, 63, 214, 0.16);
  border-radius: 18px;
  background: #fff;
  box-shadow: var(--shadow-sm);
}

.search-box:focus-within {
  border-color: var(--violet);
  box-shadow: 0 0 0 4px rgba(91, 63, 214, 0.12), var(--shadow-sm);
}

.search-icon {
  width: 22px;
  height: 22px;
  margin-left: 0.65rem;
  color: var(--violet);
}

.search-box input {
  width: 100%;
  min-width: 0;
  padding: 0.6rem 0.2rem;
  border: 0;
  outline: 0;
  background: transparent;
  font-size: 0.96rem;
}

.search-box input::placeholder {
  color: #79738b;
  opacity: 1;
}

.search-box input:focus-visible {
  outline: none;
}

.hero-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.2rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.8rem;
  padding: 0.72rem 1.25rem;
  border: 2px solid transparent;
  border-radius: 999px;
  background: linear-gradient(120deg, var(--violet), #7745d8);
  color: #fff;
  font-size: 0.92rem;
  font-weight: 750;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  box-shadow: 0 8px 20px rgba(91, 63, 214, 0.22);
  transition: transform 150ms ease, box-shadow 150ms ease, background 150ms ease;
}

.btn:hover {
  color: #fff;
  background: linear-gradient(120deg, var(--violet-dark), #5d32bd);
  box-shadow: 0 11px 24px rgba(91, 63, 214, 0.3);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.btn-secondary {
  border-color: var(--line-strong);
  background: #fff;
  color: var(--violet-dark);
  box-shadow: none;
}

.btn-secondary:hover {
  border-color: var(--violet);
  background: var(--violet-soft);
  color: var(--violet-dark);
  box-shadow: none;
}

.btn-quiet {
  border-color: var(--line-strong);
  background: #fff;
  color: var(--ink-soft);
  box-shadow: none;
}

.btn-quiet:hover {
  background: #f7f4fc;
  color: var(--ink);
  box-shadow: none;
}

.btn-small {
  min-height: 2.35rem;
  padding: 0.5rem 0.9rem;
  font-size: 0.82rem;
  box-shadow: none;
}

.btn-registered {
  border-color: #b7e6d4;
  background: var(--success-soft);
  color: var(--success);
  box-shadow: none;
}

.btn-registered:hover {
  background: #d6f4e6;
  color: var(--success);
}

.btn-wide {
  width: 100%;
  min-height: 3.1rem;
  margin-top: 0.35rem;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--violet-dark);
  font-weight: 750;
  text-decoration: none;
}

.text-link:hover {
  text-decoration: underline;
}

.text-link--arrow .icon {
  transition: transform 150ms ease;
}

.text-link--arrow:hover .icon {
  transform: translateX(3px);
}

.term-card {
  position: relative;
  overflow: hidden;
  padding: clamp(1.6rem, 3vw, 2.3rem);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-xl);
  background:
    radial-gradient(circle at 100% 0%, rgba(194, 88, 214, 0.36), transparent 40%),
    radial-gradient(circle at 0% 100%, rgba(14, 143, 125, 0.3), transparent 45%),
    #211a40;
  color: #fff;
  box-shadow: var(--shadow-lg);
  transform: rotate(1.2deg);
}

.term-card::after {
  content: "";
  position: absolute;
  right: -38px;
  bottom: -55px;
  width: 170px;
  height: 170px;
  border: 30px solid rgba(255, 255, 255, 0.06);
  border-radius: 50%;
  pointer-events: none;
}

.term-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 1.7rem;
}

.term-pill {
