  margin-bottom: 1rem;
  padding: 0;
  font-size: 1.02rem;
  font-weight: 800;
  letter-spacing: -0.015em;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.form-fieldset + .form-fieldset .field {
  margin-bottom: 0.9rem;
}

.form-fieldset + .form-fieldset .field:last-child {
  margin-bottom: 0;
}

.course-preview {
  display: flex;
  align-items: flex-start;
  gap: 0.8rem;
  margin-top: 0.8rem;
  padding: 0.9rem 1rem;
  border: 1px solid #ddd6ec;
  border-radius: 14px;
  background: #faf8ff;
  color: var(--muted);
  font-size: 0.83rem;
}

.course-preview p {
  margin: 0;
}

.course-preview__icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: var(--violet-soft);
  color: var(--violet);
}

.course-preview__icon svg {
  width: 21px;
  height: 21px;
}

.preview-course-title {
  display: block;
  margin-bottom: 0.22rem;
  color: var(--ink);
  font-size: 0.92rem;
}

.preview-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.85rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.optional-label {
  color: var(--muted);
  font-weight: 500;
}

.checkbox-field {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  margin: 1.4rem 0 1.2rem;
}

.checkbox-field input {
  flex: 0 0 auto;
  width: 1.15rem;
  height: 1.15rem;
  margin-top: 0.17rem;
  accent-color: var(--violet);
}

.checkbox-field label {
  color: var(--ink-soft);
  font-size: 0.84rem;
  line-height: 1.5;
}

.form-note {
  margin: 0.8rem 0 0;
  color: var(--muted);
  font-size: 0.74rem;
  text-align: center;
}

.schedule-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.schedule-heading h2 {
  margin-bottom: 0;
}

.schedule-summary {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.8rem;
  margin-bottom: 1.2rem;
  padding: 1.1rem;
  border-radius: 18px;
  background:
    radial-gradient(circle at 100% 0%, rgba(232, 85, 114, 0.14), transparent 45%),
    linear-gradient(125deg, #f2eeff, #e9faf5);
}

.schedule-summary > div {
  display: flex;
  flex-direction: column;
  padding-left: 0.8rem;
  border-left: 3px solid var(--violet);
}

.schedule-summary > div:last-child {
  border-left-color: var(--teal);
}

.summary-value {
  color: var(--ink);
  font-size: 1.8rem;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.04em;
}

.summary-label {
  margin-top: 0.18rem;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 650;
}

.table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #fff;
}

.table-wrap:focus-visible {
  outline: 3px solid #1369c9;
  outline-offset: 2px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
}

th,
td {
  padding: 0.75rem 0.7rem;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: middle;
}

thead th {
  background: #f6f3fc;
  color: var(--ink-soft);
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

tbody th {
  color: var(--ink);
  font-size: 0.8rem;
  white-space: nowrap;
}

tbody tr:last-child th,
tbody tr:last-child td {
  border-bottom: 0;
}

tbody tr:hover {
  background: #fcfaff;
}

tfoot th,
tfoot td {
  border-top: 1px solid var(--line-strong);
  border-bottom: 0;
  background: #fbfaff;
  font-weight: 800;
}

.table-course-title {
  display: block;
  min-width: 130px;
  color: var(--ink-soft);
  font-weight: 600;
}

.table-schedule {
  display: block;
  min-width: 160px;
  color: var(--muted);
  font-size: 0.76rem;
}

.btn-drop {
  min-height: 2rem;
  padding: 0.32rem 0.62rem;
  border: 1px solid #f0c0c3;
  border-radius: 999px;
  background: #fff5f5;
  color: #971e25;
  font-size: 0.71rem;
  font-weight: 750;
  white-space: nowrap;
}

.btn-drop:hover {
  background: #ffe9ea;
  border-color: #df8e93;
}

.schedule-tip {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  margin-top: 1.2rem;
  padding: 0.9rem;
  border: 1px solid #f4ddb2;
  border-radius: 14px;
  background: #fff9eb;
  color: #5d4a24;
  font-size: 0.78rem;
}

.schedule-tip p {
  margin: 0;
}

.tip-icon {
  flex: 0 0 auto;
  color: var(--gold);
}

.tip-icon svg {
  width: 22px;
  height: 22px;
}

.status-banner {
  margin-bottom: 1.2rem;
  padding: 0.85rem 1rem;
  border: 1px solid #a9dfca;
  border-left: 4px solid var(--teal);
  border-radius: 12px;
  background: var(--success-soft);
  color: var(--success);
  font-size: 0.85rem;
  font-weight: 600;
  line-height: 1.45;
}

.status-banner::before {
  content: "✓";
  margin-right: 0.45rem;
  font-weight: 800;
}

.modal {
  width: min(calc(100% - 2rem), 520px);
  max-height: calc(100vh - 2rem);
  padding: 0;
  overflow: auto;
  border: 0;
  border-radius: var(--radius-lg);
  background: #fff;
  color: var(--ink);
  box-shadow: 0 35px 90px rgba(15, 10, 40, 0.4);
}

.modal::backdrop {
  background: rgba(22, 17, 45, 0.62);
  backdrop-filter: blur(3px);
}

.modal[open] {
  animation: modal-in 180ms ease-out;
}

.modal-inner {
  position: relative;
  padding: clamp(1.5rem, 4vw, 2.2rem);
}

.modal-close {
  position: absolute;
  top: 0.9rem;
  right: 0.9rem;
  display: grid;
  place-items: center;
  width: 2.3rem;
  height: 2.3rem;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: #f4f1fb;
  color: var(--ink-soft);
}

.modal-close:hover {
  background: #e9e3f8;
  color: var(--ink);
}

.modal-close svg {
  width: 18px;
  height: 18px;
}

.modal-icon {
  display: grid;
  place-items: center;
  width: 3.5rem;
  height: 3.5rem;
  margin-bottom: 1.1rem;
  border-radius: 18px;
  background: var(--success-soft);
  color: var(--teal);
}

.modal-icon svg {
  width: 28px;
  height: 28px;
}

.modal--danger .modal-icon {
  background: var(--danger-soft);
  color: var(--danger);
}

.modal--danger .modal-icon svg {
  width: 24px;
  height: 24px;
}

.modal h2 {
  margin-bottom: 0.55rem;
  font-size: clamp(1.5rem, 4vw, 1.9rem);
}

.modal > .modal-inner > p {
  margin-bottom: 1.3rem;
  color: var(--muted);
  font-size: 0.9rem;
}

.modal-details {
  margin-bottom: 1.4rem;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: #faf8ff;
}

.modal-details dl {
  display: grid;
  gap: 0.6rem;
  margin: 0;
}

.modal-details dl > div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid var(--line);
}

.modal-details dl > div:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.modal-details dt {
  color: var(--muted);
  font-size: 0.78rem;
}

.modal-details dd {
  margin: 0;
  color: var(--ink);
  font-size: 0.83rem;
  font-weight: 700;
  text-align: right;
}

.modal-details .modal-warning {
  margin: 0;
  color: var(--ink-soft);
  font-size: 0.82rem;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.7rem;
}

.btn-danger {
  border-color: transparent;
  background: #b4232b;
  color: #fff;
  box-shadow: 0 8px 20px rgba(180, 35, 43, 0.2);
}

.btn-danger:hover {
  background: #941a21;
  color: #fff;
}

@keyframes modal-in {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.profile-section {
  padding-bottom: 2.6rem;
}

.profile-banner {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  overflow: hidden;
  margin-top: 0.7rem;
  padding: clamp(1.5rem, 3.5vw, 2.3rem);
  border-radius: var(--radius-lg);
  background:
    radial-gradient(circle at 96% 15%, rgba(247, 213, 111, 0.24), transparent 25%),
    radial-gradient(circle at 15% 130%, rgba(111, 224, 200, 0.23), transparent 35%),
    linear-gradient(120deg, #3b248f, #6734b6 52%, #a2398d);
  color: #fff;
  box-shadow: var(--shadow-md);
}

.profile-banner::after {
  content: "";
  position: absolute;
  right: 20%;
  bottom: -90px;
  width: 220px;
  height: 220px;
  border: 34px solid rgba(255, 255, 255, 0.06);
  border-radius: 50%;
  pointer-events: none;
}

.profile-identity {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 1.3rem;
}

.profile-avatar {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 96px;
  height: 96px;
  border: 4px solid rgba(255, 255, 255, 0.35);
  border-radius: 50%;
  background: linear-gradient(145deg, #ffd872, #f47a88);
  color: #3b1900;
  font-size: 1.9rem;
  font-weight: 800;
  letter-spacing: -0.04em;
  box-shadow: 0 12px 28px rgba(20, 10, 50, 0.25);
}

.profile-identity h2 {
  margin-bottom: 0.28rem;
  color: #fff;
  font-size: clamp(1.8rem, 3.4vw, 2.5rem);
}

.profile-program {
  margin-bottom: 0.8rem;
  color: #e4dcff;
  font-size: 0.93rem;
  font-weight: 600;
}

.profile-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.profile-tags li {
  padding: 0.3rem 0.65rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.11);
  color: #fff;
  font-size: 0.74rem;
}

.profile-tag-label {
  margin-right: 0.28rem;
  color: #d7ccff;
}

.profile-actions {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.65rem;
}

.profile-actions .btn {
  background: #fff;
  color: var(--violet-dark);
  box-shadow: 0 10px 24px rgba(20, 10, 50, 0.16);
}

.profile-actions .btn:hover {
  background: #f5f0ff;
  color: var(--violet-dark);
}

.profile-actions .btn-secondary {
  border-color: rgba(255, 255, 255, 0.42);
  background: transparent;
  color: #fff;
  box-shadow: none;
}

.profile-actions .btn-secondary:hover {
  border-color: #fff;
  background: rgba(255, 255, 255, 0.13);
  color: #fff;
}

.profile-actions .btn:focus-visible {
  outline-color: #ffd166;
}

.profile-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(320px, 0.82fr);
  align-items: start;
  gap: 1.7rem;
  margin-top: 1.7rem;
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin-top: 1.3rem;
}

.status-inline {
  margin: 0;
  color: var(--success);
  font-size: 0.82rem;
  font-weight: 650;
}

.academic-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.8rem;
  margin: 0 0 1.3rem;
}

.stat-card {
  padding: 1rem;
  border-radius: 16px;
}

.stat-card--violet {
  background: #eee9ff;
}

.stat-card--coral {
  background: #ffe9ed;
}

.stat-card--teal {
  background: #dff8f2;
}

.stat-card--gold {
  background: #fff3d4;
}

.stat-card dt {
  color: var(--ink-soft);
  font-size: 0.69rem;
  font-weight: 750;
  letter-spacing: 0.04em;
}

.stat-card dd {
  margin: 0.2rem 0 0;
  color: var(--ink);
  font-size: 1.65rem;
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.04em;
}

.degree-progress {
  margin-bottom: 1.3rem;
}

.degree-progress-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.5rem;
}

.degree-progress-heading h3 {
  margin: 0;
  font-size: 0.85rem;
}

.degree-progress-heading span {
  color: var(--muted);
  font-size: 0.75rem;
}

.progress-track {
  height: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: #efecf5;
}

.progress-track > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--violet), #a63cc4, var(--coral));
}

.advisor-list {
  display: grid;
  gap: 0.5rem;
  margin: 0;
  padding-top: 1.1rem;
  border-top: 1px solid var(--line);
}

.advisor-list > div {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.advisor-list dt {
  color: var(--muted);
  font-size: 0.78rem;
}

.advisor-list dd {
  margin: 0;
  color: var(--ink-soft);
  font-size: 0.78rem;
  font-weight: 650;
  text-align: right;
}

.schedule-section {
  padding-top: 2.2rem;
  background:
    radial-gradient(circle at 95% 20%, rgba(91, 63, 214, 0.06), transparent 25%),
    #fbfafc;
}

.panel-table {
  border-radius: 20px;
  box-shadow: var(--shadow-sm);
}

.schedule-section table th,
.schedule-section table td {
  padding: 0.85rem 0.8rem;
}

@media (max-width: 1000px) {
  .hero-grid {
    grid-template-columns: minmax(0, 1fr) minmax(280px, 0.8fr);
    gap: 2.2rem;
  }

  .hero h1 {
    font-size: clamp(2.6rem, 6vw, 3.8rem);
  }

  .registration-layout,
  .profile-layout {
    grid-template-columns: 1fr;
  }

  .schedule-panel {
    order: -1;
  }

  .filter-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .filter-reset-wrap {
    grid-column: 1 / -1;
  }

  .filter-reset-wrap .btn {
    width: auto;
  }

  .profile-banner {
    align-items: flex-start;
  }
}

@media (max-width: 820px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.35rem;
    padding-block: 0.65rem;
  }

  .main-nav {
    width: 100%;
  }

  .main-nav ul {
    gap: 0.1rem;
  }

  .main-nav a {
    padding: 0.5rem 0.65rem;
    font-size: 0.85rem;
  }

  .hero {
    padding-top: 3.2rem;
  }

  .hero-grid {
    grid-template-columns: 1fr;
  }

  .hero h1 {
    max-width: 13ch;
  }

  .term-card {
    max-width: 520px;
    transform: none;
  }

  .stats-strip {
    grid-template-columns: repeat(2, 1fr);
  }

  .stats-strip > div:nth-child(2) {
    border-right: 0;
  }

  .stats-strip > div:nth-child(-n + 2) {
    border-bottom: 1px solid var(--line);
  }

  .steps,
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.8rem;
  }

  .section-heading .text-link {
    margin-top: 0.2rem;
  }

  .page-hero-content {
    align-items: flex-start;
    flex-direction: column;
    gap: 2rem;
  }

  .catalog-stamp {
    width: 110px;
    height: 110px;
  }

  .catalog-stamp-number {
    font-size: 2rem;
  }

  .hero-mini-stack {
    padding-left: 1rem;
  }

  .mini-course {
    width: 70px;
    height: 88px;
  }

  .filter-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .filter-reset-wrap {
    grid-column: 1 / -1;
  }

  .results-bar {
    align-items: flex-start;
    flex-direction: column;
    gap: 0.7rem;
  }

  .profile-banner {
    align-items: flex-start;
    flex-direction: column;
  }

  .profile-actions {
    justify-content: flex-start;
  }

  .footer-grid {
    gap: 2rem;
  }
}

@media (max-width: 620px) {
  .container {
    width: min(calc(100% - 1.5rem), var(--container));
  }

  .brand-mark {
    width: 40px;
    height: 40px;
  }

  .brand-text > span {
    font-size: 1.1rem;
  }

  .main-nav ul {
    justify-content: flex-start;
  }

  .main-nav a {
    font-size: 0.8rem;
    padding: 0.46rem 0.56rem;
  }

  .nav-badge {
    min-width: 1.2rem;
    height: 1.2rem;
    font-size: 0.64rem;
  }

  .hero {
    padding-bottom: 4.5rem;
  }

  .hero h1 {
    font-size: clamp(2.35rem, 12vw, 3.1rem);
  }

  .hero-search .search-box {
    flex-wrap: wrap;
    padding: 0.55rem;
  }

  .search-box input {
    flex: 1 1 calc(100% - 50px);
    padding-block: 0.4rem;
  }

  .hero-search .btn {
    width: 100%;
  }

  .stats-section {
    margin-top: -2.4rem;
  }

  .stats-strip > div {
    padding: 1rem;
  }

  .stats-strip dt {
    font-size: 0.62rem;
  }

  .stats-strip dd {
    font-size: 1.55rem;
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .course-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .course-card__footer .btn {
    width: 100%;
  }

  .filter-grid,
  .form-grid,
  .academic-stats {
    grid-template-columns: 1fr;
  }

  .field--full {
    grid-column: auto;
  }

  .filter-reset-wrap {
    grid-column: auto;
  }

  .filter-reset-wrap .btn {
    width: 100%;
  }

  .results-bar .field--inline {
    width: 100%;
  }

  .results-bar .field--inline select {
    flex: 1;
  }

  .schedule-heading {
    flex-direction: column;
  }

  .schedule-summary {
    padding: 0.9rem;
  }

  .summary-value {
    font-size: 1.5rem;
  }

  .profile-identity {
    align-items: flex-start;
    flex-direction: column;
  }

  .profile-avatar {
    width: 78px;
    height: 78px;
    font-size: 1.55rem;
  }

  .profile-tags {
    flex-direction: column;
    align-items: flex-start;
  }

  .profile-actions {
    width: 100%;
  }

  .profile-actions .btn {
    width: 100%;
  }

  .modal-actions {
    flex-direction: column-reverse;
  }

  .modal-actions .btn {
    width: 100%;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 390px) {
  .main-nav a {
    font-size: 0.75rem;
    padding-inline: 0.45rem;
  }

  .brand-text small {
    letter-spacing: 0.1em;
  }

  .eyebrow {
    font-size: 0.68rem;
  }

  .hero-links {
    align-items: stretch;
    flex-direction: column;
  }

  .hero-links .btn {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@media (prefers-contrast: more) {
  :root {
    --line: #8a829e;
    --line-strong: #6e6684;
    --muted: #49425f;
  }

  .btn,
  .course-card,
  .panel,
  .filter-panel {
    border-width: 2px;
  }
}

@media print {
  .site-header,
  .site-footer,
  .page-hero,
  .profile-actions,
  .profile-layout,
  .schedule-section .section-heading .text-link,
  .status-banner,
  .btn-drop,
  .skip-link {
    display: none !important;
  }

  body {
    background: #fff;
