 const errors=[]; page.on('pageerror',e=>errors.push('pageerror: '+e.message)); page.on('console',m=>{if(m.type()==='error') errors.push('console: '+m.text())});
 const base='http://127.0.0.1:4173/';
 await page.goto(base); await page.waitForTimeout(300);
 console.log('home cards', await page.locator('.course-card').count(), 'badge', await page.locator('.nav-badge').first().textContent());
 // all pages 200-ish via nav
 const nav=page.getByRole('navigation',{name:'Primary navigation'});
 for (const name of ['Courses','Registration','Profile','Home']) {
  const link=nav.getByRole('link',{name:new RegExp('^'+name)});
  await link.click(); await page.waitForLoadState('load');
  console.log(name, await page.locator('h1').first().textContent(), await page.locator('.skip-link').count());
 }
 // search from home
 await page.fill('#home-search','robotics'); await page.press('#home-search','Enter'); await page.waitForTimeout(300);
 console.log('empty summary', await page.locator('#results-summary').textContent(), 'empty', await page.locator('#no-results').isVisible());
 await page.click('#empty-reset'); await page.waitForTimeout(100);
 const before=await page.locator('.course-card').count();
 await page.selectOption('#department-filter','Design'); await page.waitForTimeout(100);
 console.log('design filter', await page.locator('.course-card').count(), 'of', before);
 await page.selectOption('#level-filter','300'); await page.waitForTimeout(100);
 console.log('design300', await page.locator('#results-summary').textContent());
 await page.click('#clear-filters');
 // registration
 await page.goto(base+'registration.html'); await page.waitForTimeout(200);
 const initialRows=await page.locator('#schedule-body tr').count();
 console.log('initial rows',initialRows);
 // submit empty gives errors incl course/agreement
 await page.click('button[type=submit]'); await page.waitForTimeout(100);
 console.log('errors', await page.locator('.field-error:not(:empty)').count(), 'summary', await page.locator('#form-error-summary').isVisible());
 // select course and check
 await page.selectOption('#course-select','psy-265'); await page.check('#reg-agreement');
 await page.click('button[type=submit]'); await page.waitForTimeout(200);
 console.log('modal open/focus', await page.locator('#confirm-dialog').evaluate(el=>el.open), await page.evaluate(()=>document.activeElement.id));
 // cancel via go back
 await page.getByRole('button',{name:'Go back'}).click(); await page.waitForTimeout(100);
 console.log('modal canceled', await page.locator('#confirm-dialog').evaluate(el=>el.open), 'focus', await page.evaluate(()=>document.activeElement.textContent.trim().slice(0,30)));
 // reopen confirm
 await page.click('button[type=submit]'); await page.waitForTimeout(100);
 await page.click('#confirm-action'); await page.waitForTimeout(200);
 console.log('rows after add', await page.locator('#schedule-body tr').count(), 'status', (await page.locator('#registration-status').textContent()).slice(0,50));
 // drop the new course by label
 const dropButtons=page.locator('[data-drop-course]');
 console.log('drop buttons', await dropButtons.count());
 await dropButtons.last().click(); await page.waitForTimeout(100);
 console.log('drop title', await page.locator('#confirm-title').textContent());
 await page.click('#confirm-action'); await page.waitForTimeout(200);
 console.log('rows after drop', await page.locator('#schedule-body tr').count(), 'status', (await page.locator('#registration-status').textContent()).slice(0,50));
 // profile update then persist back registration prefill
 await page.goto(base+'profile.html'); await page.waitForTimeout(200);
 await page.fill('#profile-full-name','Maya Thompson'); await page.click('#profile-form button[type=submit]'); await page.waitForTimeout(100);
 console.log('profile status', await page.locator('#profile-status').textContent());
 await page.goto(base+'registration.html'); await page.waitForTimeout(200);
 console.log('prefilled name', await page.inputValue('#reg-name'));
 // widths mobile
 await page.setViewportSize({width:390,height:844});
 for (const f of ['index.html','courses.html','registration.html','profile.html']) {
  await page.goto(base+f); await page.waitForTimeout(200);
  console.log(f, 'scroll', await page.evaluate(()=>document.documentElement.scrollWidth));
 }
 console.log('ERRORS', errors);
 await browser.close();
})();
EOF
