const { chromium } = require('playwright');
(async()=>{const b=await chromium.launch();const c=await b.newContext();const p=await c.newPage();
for (const w of [320,360,390,768,900,1024,1280,1440]) {
 await p.setViewportSize({width:w,height:900});
 const rows=[];
 for (const f of ['index.html','courses.html','registration.html','profile.html']) {
  await p.goto('http://127.0.0.1:4173/'+f); await p.waitForTimeout(120);
  rows.push(f.replace('.html','')+':'+await p.evaluate(()=>document.documentElement.scrollWidth));
 }
 console.log(w, rows.join(' '));
}
await b.close();})();
EOF
