const { chromium } = require('playwright');
(async()=>{const b=await chromium.launch();const c=await b.newContext({viewport:{width:1280,height:900}});const p=await c.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));await p.goto('http://127.0.0.1:4173/registration.html');await p.waitForTimeout(200);await p.locator('[data-drop-course]').first().click();await p.waitForTimeout(100);console.log('open focus',await p.evaluate(()=>document.activeElement.id));await p.click('#confirm-action');await p.waitForTimeout(200);console.log('after drop focus',await p.evaluate(()=>document.activeElement.id),'rows',await p.locator('#schedule-body tr').count(),'errs',errs);await b.close();})();
EOF
